command:
// ==========================================
// LUNAS WIRKUNG: ZIELSCHEIBE (ZERZAL)
//
// - Ahne: Zerzal (Effektbild von Zerzal)
// - Bedingung: Setzt einen aktiven "Weißen Speer" voraus
// - Ziel: 1 ausgewähltes lebendes Ziel per Target (max. 16 Schritt)
// - Dauer: QS × 2 Kampfrunden
// - Effektanlage auf dem Caster (Angriffsbonus mit dem Weißen Speer auf das Ziel)
// - eine Karte + roter GM-Button über Block 19.8
// ==========================================

(async function () {
    const macroUuid = this?.uuid || game.macros.getName("Zielscheibe")?.uuid || null;

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt = !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register || !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde || !globalThis.DSK?.Geometrie?.Distanz || !globalThis.DSK?.Wesen?.IstLebendig || !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden || !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen || !globalThis.DSK?.GabenUI?.GMMakroButton || !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen || !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
        await fwMacro.execute(); await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;
    if (!DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register || !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde || !DSK_FW?.Geometrie?.Distanz || !DSK_FW?.Wesen?.IstLebendig || !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden || !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen || !DSK_FW?.GabenUI?.GMMakroButton || !DSK_FW?.GabenUI?.AnfrageKarteErstellen || !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht vollständig geladen!");

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

    const gabenName = "Zielscheibe", vollerName = "Zielscheibe (Zerzal)", ahne = "Zerzal";
    const reaktionsKey = "zerzalZielscheibe", flagKey = "pendingZielscheibeZerzal";
    const iconBild = DSK_FW.Symbol(ahne);
    const maxReichweite = 16;
    const endeText = "Du verlierst deine Beute aus dem Fokus. Dein Angriff sinkt wieder auf den Normalwert.";

    DSK_FW.EffektEnde.Register(reaktionsKey, vollerName, endeText);

    // +++ 3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++

    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
        if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
    };

    const ladeActor = async uuid => {
        if (!uuid) return null;
        try {
            const doc = await fromUuid(uuid);
            return doc?.documentName === "Token" ? doc.actor : doc || null;
        } catch (error) {
            console.warn("Zielscheibe: Actor konnte nicht geladen werden.", { uuid, error });
            return null;
        }
    };

    const istGueltigesLebewesen = actor => {
        if (!actor) return false;
        return DSK_FW.Wesen.IstLebendig(actor, { zusaetzlichAusgeschlossen: ["elementar"] });
    };

    const findeSpeer = actor => (actor?.effects || []).find(e =>
        !e.disabled && String(e.name || e.label || "").toLowerCase().includes("weißer speer")
    ) || null;

    const findeAlteEffekte = (actor, casterUuid) => (actor?.effects || []).filter(e =>
        (e.name || e.label || "") === vollerName &&
        e.getFlag("dsk", "isZielscheibe") === true &&
        e.getFlag("dsk", "casterUuid") === casterUuid
    );

    const beschreibungFuer = (zielName, qs, kampfRunden) =>
        `Das Zerzalkind erklärt <b>${zielName}</b> zu seiner Beute.` +
        `<br><br>Bei Angriffen auf dieses Ziel mit dem <b>Weißen Speer</b> ist der Angriffswert um <b>+${qs}</b> erhöht.` +
        `<br><br><b>Wirkungsdauer:</b> ${kampfRunden} Kampfrunden (${qs} QS × 2)` +
        `<br><br><b>Zielkategorie:</b> Sich selbst (Beute: ${zielName})`;

    // +++ 4 - ZIELSCHEIBE AUF GM-CLIENT ANLEGEN +++++++++++++++

    const wendeZielscheibeAn = async ({ casterActor, casterName, qs, zielName, zielUuid }) => {
        if (!casterActor || !DSK_FW.Schaden.IstAktiverGM()) return false;

        const aktiverSpeer = findeSpeer(casterActor);
        if (!aktiverSpeer) {
            ui.notifications.warn(`Luna sagt 🌙: Der Weiße Speer von ${casterName} ist nicht mehr aktiv.`);
            return false;
        }

        const kampfRunden = qs * 2;
        const dauerText = `${kampfRunden} Kampfrunde(n) (${qs} QS × 2 KR)`;
        const beschreibung = beschreibungFuer(zielName, qs, kampfRunden);
        const effIcon = aktiverSpeer.img || aktiverSpeer.icon || iconBild;
        const finalEffektName = `${vollerName} - ${zielName}`;

        const alteEffekte = findeAlteEffekte(casterActor, casterActor.uuid);
        if (alteEffekte.length) await casterActor.deleteEmbeddedDocuments("ActiveEffect", alteEffekte.map(e => e.id));

        let zielscheibeEffect = null;
        try {
            zielscheibeEffect = await DSK_FW.Effekt.Anwenden({
                name: finalEffektName, ahne,
                beschreibung: `${beschreibung}<br><br><b>Wirkungsdauer:</b> ${dauerText}`,
                gabeZiel: "", qs, ziel: casterActor,
                duration: { rounds: kampfRunden, startTime: game.time.worldTime },
                showIcon: 1, icon: effIcon,
                changes: [
                    { key: "system.rangeStats.attack", mode: 2, value: `${qs}`, priority: 20 },
                    { key: "system.meleeStats.attack", mode: 2, value: `${qs}`, priority: 20 }
                ],
                flags: { dsk: {
                    isZielscheibe: true, casterUuid: casterActor.uuid, casterName, qs,
                    zielName, zielUuid,
                    wirkungsende: { sfName: reaktionsKey, basisEffektName: finalEffektName, beschreibungFuerEnde: endeText }
                }}
            });

            if (!zielscheibeEffect) throw new Error("Block 5 hat keinen Zielscheibe-Effekt zurückgegeben.");

            const endeDaten = zielscheibeEffect.getFlag("dsk", "wirkungsende");
            const effektErfolgreich =
                (zielscheibeEffect.name || zielscheibeEffect.label || "") === finalEffektName &&
                zielscheibeEffect.getFlag("dsk", "isZielscheibe") === true &&
                zielscheibeEffect.getFlag("dsk", "casterUuid") === casterActor.uuid &&
                Number(zielscheibeEffect.getFlag("dsk", "qs")) === qs &&
                zielscheibeEffect.getFlag("dsk", "zielUuid") === zielUuid &&
                endeDaten?.sfName === reaktionsKey &&
                endeDaten?.basisEffektName === finalEffektName &&
                endeDaten?.beschreibungFuerEnde === endeText;

            if (!effektErfolgreich) throw new Error("Der Zielscheibe-Effekt wurde nicht vollständig angelegt.");

            return true;
        } catch (error) {
            console.error("Zielscheibe: Effektanlage fehlgeschlagen.", { casterActor: casterActor.name, zielName, qs, error });
            if (zielscheibeEffect) await zielscheibeEffect.delete();
            return false;
        }
    };

    // +++ 5 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++

    const verarbeiteAnfrage = async (casterActor, daten) => {
        if (!casterActor || !daten || !game.user.isGM) return false;
        if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) return false;
        if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
            ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
            return false;
        }

        const casterToken = DSK_FW.Token.Finde(casterActor, daten.casterTokenId, daten.casterTokenUuid);
        if (!casterToken) return false;

        const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
        const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
        const zielName = String(daten.zielName || "").trim();
        const zielUuid = String(daten.zielUuid || "").trim();

        const erfolgreich = Boolean(zielName && await wendeZielscheibeAn({ casterActor, casterName, qs, zielName, zielUuid }));

        await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
            messageId: daten.messageId, gabenName: vollerName, ahne,
            beschreibung: daten.beschreibung || "", wirkender: casterName,
            ziele: erfolgreich ? [{ name: zielName, rolle: "Beute markiert (+QS Angriff)" }] : [],
            misserfolge: erfolgreich ? [] : [{ name: casterName, grund: "Weißer Speer nicht aktiv oder Effekt konnte nicht angelegt werden" }],
            dauerText: `${qs * 2} Kampfrunde(n) (${qs} QS × 2)`, erfolgreich
        });

        if (erfolgreich) ui.notifications.info(`Luna sagt 🌙: Zielscheibe auf ${zielName} aktiviert.`);
        else ui.notifications.error("Luna sagt 🌙: Zielscheibe konnte nicht aktiviert werden (Ist der Weiße Speer aktiv?).");
        return true;
    };

    // +++ 6 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++

    if (game.user.isGM) {
        const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);
        if (anfragen.length) {
            for (const anfrageActor of anfragen) {
                const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
                if (!daten) continue;
                if (await verarbeiteAnfrage(anfrageActor, daten)) await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
            }
            return;
        }
    }

    // +++ 7 - WIRKENDER + QS + WEISSER SPEER ++++++++++++++++++

    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;
    if (!casterActor) casterActor =
        canvas.tokens.placeables.map(t => t.actor).find(a => a?.getFlag("world", "letzteGabenQS") !== undefined) ||
        game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined) || null;

    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus!");
    if (!game.user.isGM && !casterActor.isOwner) return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");

    const casterToken = DSK_FW.Token.Finde(casterActor);
    if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene für die Entfernungsberechnung!");

    const casterName = DSK_FW.ResolveTokenName(casterActor);
    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor, gabenName,
        suchbegriffe: ["Zielscheibe Probe", "Zielscheibe"],
        testDataObj: typeof testData !== "undefined" ? testData : null,
        fallback: 0, protokollieren: true
    });

    if (qs <= 0) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.warn("Luna sagt 🌙: Die Probe ist fehlgeschlagen oder die Qualitätsstufe konnte nicht ermittelt werden!");
    }

    // Bedingung prüfen: Weißer Speer muss aktiv sein
    const aktiverSpeer = findeSpeer(casterActor);
    if (!aktiverSpeer) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName, ahne,
            beschreibung: "Die Zielscheibe verfehlt ihre Wirkung: Es ist kein aktiver **Weißer Speer** gefunden worden.",
            wirkender: casterName, ziele: [],
            misserfolge: [{ name: casterName, grund: "Kein aktiver Weißer Speer" }],
            dauerText: "0 Kampfrunden", gmBereich: false,
            angewendet: true, erfolgreich: false, anfragenderUserId: game.user.id
        });
        await raeumeQSAuf(casterActor);
        return;
    }

    // Ziel per Target prüfen (genau 1 lebendiges Ziel im Umkreis von max. 16 Schritt)
    const targets = Array.from(game.user.targets || []);
    if (!targets.length) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.warn("Luna sagt 🌙: Bitte wähle ein Ziel per Target aus!");
    }

    const zielToken = targets[0];
    const zielActor = zielToken?.actor;
    const zielName = zielToken?.name || zielActor?.name || "Unbekanntes Ziel";

    if (!zielActor || !istGueltigesLebewesen(zielActor)) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.warn("Luna sagt 🌙: Das ausgewählte Ziel muss ein lebendiges Wesen sein!");
    }

    const distanz = Math.round(DSK_FW.Geometrie.Distanz(casterToken, zielToken) * 10) / 10;
    if (distanz > maxReichweite) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.warn(`Luna sagt 🌙: Das Ziel ist zu weit entfernt (${distanz} Schritt, max. ${maxReichweite}).`);
    }

    const kampfRunden = qs * 2;
    const dauerText = `${kampfRunden} Kampfrunden (${qs} QS × 2)`;
    const beschreibung = beschreibungFuer(zielName, qs, kampfRunden);

    // +++ 8 - GEMEINSAME KARTE + GM-ANFRAGE +++++++++++++++++++

    const gmLink = DSK_FW.GabenUI.GMMakroButton(
        macroUuid, "Effekt anwenden",
        "Das Makro muss durch die Spielleitung ausgeführt werden."
    );

    const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne, beschreibung, wirkender: casterName,
        ziele: [{ name: zielName, rolle: "Als Beute markiert" }],
        misserfolge: [], dauerText,
        gmLink, gmBereich: !game.user.isGM,
        anfragenderUserId: game.user.id
    });

    if (!nachricht) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.error("Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!");
    }

    const anfrageDaten = {
        casterUuid: casterActor.uuid, casterName,
        casterTokenId: casterToken.id,
        casterTokenUuid: casterToken.document?.uuid || casterToken.uuid || null,
        qs, zielName, zielUuid: zielActor.uuid, beschreibung,
        sceneId: canvas.scene?.id || null,
        requestedByUserId: game.user.id,
        messageId: nachricht.id, macroUuid, erstellt: Date.now()
    };

    if (game.user.isGM) {
        await verarbeiteAnfrage(casterActor, anfrageDaten);
        await raeumeQSAuf(casterActor);
        return;
    }

    await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, anfrageDaten);
    await raeumeQSAuf(casterActor);
    ui.notifications.info("Luna sagt 🌙: Zielscheibe wurde bei der Spielleitung zur Anwendung beantragt.");

}).call(this);
